from datetime import datetime, timedelta
from collections import defaultdict


def _next_month(ym):
    y = int(ym[:4])
    m = int(ym[5:7])
    y += 1
    m += 1
    if m > 12:
        m = 1
        y += 1
    return "%04d-%02d" % (y, m)


def _add_months(ym, offset):
    y = int(ym[:4])
    m = int(ym[5:7])
    idx = y * 12 + (m - 1) + offset
    return "%04d-%02d" % (idx // 12, idx % 12 + 1)


def analyze(data, plan):
    orders = data.get("orders", [])
    customers = data.get("customers", [])

    incl = set(plan.get("included_statuses") or [])
    tf = plan.get("time_field") or "order_purchase_timestamp"
    start = plan.get("start")
    end = plan.get("end")

    uid_of = {}
    for c in customers:
        cid = c.get("customer_id")
        if cid:
            uid_of[cid] = c.get("customer_unique_id") or cid

    # observation horizon H
    if end:
        H = datetime.strptime(end, "%Y-%m-%dT%H:%M:%S")
    else:
        max_t = ""
        for o in orders:
            t = o.get(tf) or ""
            if t > max_t:
                max_t = t
        H = datetime.strptime(max_t, "%Y-%m-%dT%H:%M:%S") + timedelta(seconds=1)
    Hs = H.strftime("%Y-%m-%dT%H:%M:%S")

    def complete_month(ym):
        y = int(ym[:4])
        m = int(ym[5:7])
        nxt = datetime(y, m, 1) + timedelta(days=32)
        nxt = datetime(nxt.year, nxt.month, 1)
        return nxt <= H

    # active orders: included status, non-empty time, T < H
    first = {}
    activity = defaultdict(set)
    for o in orders:
        st = o.get("order_status")
        if st not in incl:
            continue
        t = o.get(tf) or ""
        if not t or t >= Hs:
            continue
        cid = o.get("customer_id")
        uid = uid_of.get(cid, cid)
        if not uid:
            continue
        key = (t, o.get("order_id") or "")
        cur = first.get(uid)
        if cur is None or key < cur:
            first[uid] = key
        activity[uid].add(t[:7])

    cohorts = defaultdict(set)
    for uid, (ft, _oid) in first.items():
        if start and ft < start:
            continue
        cohorts[ft[:7]].add(uid)

    rows = []
    total_customers = 0
    for cohort in sorted(cohorts.keys()):
        if not complete_month(cohort):
            continue
        members = cohorts[cohort]
        cnt = len(members)
        total_customers += cnt
        for offset in range(0, 7):
            target = _add_months(cohort, offset)
            if not complete_month(target):
                break
            retained = sum(1 for uid in members if target in activity[uid])
            rows.append({
                "cohort": cohort,
                "offset": offset,
                "customer_count": cnt,
                "retained_count": retained,
                "retention": ratio(retained, cnt),
            })

    # last complete month (global)
    last_complete = None
    m = "2016-01"
    guard = 0
    while guard < 240:
        if not complete_month(m):
            break
        last_complete = m
        m = _next_month(m)
        guard += 1

    return {
        "kind": "cohort_retention",
        "total": {
            "customer_count": total_customers,
            "last_complete_month": last_complete,
        },
        "rows": rows,
    }

def analyze(data, plan):
    from collections import defaultdict

    kind = plan.get("kind")
    statuses = set(plan.get("included_statuses") or [])
    start = plan.get("start")
    end = plan.get("end")
    prev_start = plan.get("previous_start")
    prev_end = plan.get("previous_end")
    T = plan.get("time_field")
    amount_source = plan.get("amount_source")
    group_by = plan.get("group_by")

    def ratio(numerator, denominator):
        if not denominator:
            return None
        return format(Decimal(numerator) / Decimal(denominator), ".6f")

    def in_window(t, s, e):
        if not t:
            return False
        if s is not None and t < s:
            return False
        if e is not None and t >= e:
            return False
        return True

    def month_next(m):
        y = int(m[0:4]); mo = int(m[5:7])
        if mo == 12:
            return "%04d-01" % (y + 1)
        return "%04d-%02d" % (y, mo + 1)

    orders = data.get("orders", [])
    customers = {c["customer_id"]: c for c in data.get("customers", [])}

    def order_amount(oid):
        total = 0
        if amount_source == "payments":
            for p in data.get("order_payments", []):
                if p["order_id"] == oid:
                    total += int(p.get("payment_value_cents") or 0)
        else:
            for it in data.get("order_items", []):
                if it["order_id"] == oid:
                    total += int(it.get("price_cents") or 0) + int(it.get("freight_cents") or 0)
        return total

    def included(s, e):
        out = []
        for o in orders:
            if o.get("order_status") in statuses and in_window(o.get(T), s, e):
                out.append(o)
        return out

    def group_of(order):
        if group_by == "customer_state":
            c = customers.get(order.get("customer_id"))
            return (c or {}).get("customer_state") or "unknown"
        if group_by == "purchase_date":
            return (order.get(T) or "")[:10]
        if group_by == "purchase_month":
            return (order.get(T) or "")[:7]
        return str(order.get(group_by)) if group_by else None

    def build(s, e):
        agg = defaultdict(lambda: {"order_count": 0, "amount_cents": 0})
        total_count = 0
        total_amount = 0
        for o in included(s, e):
            amt = order_amount(o["order_id"])
            total_count += 1
            total_amount += amt
            if group_by:
                g = group_of(o)
                agg[g]["order_count"] += 1
                agg[g]["amount_cents"] += amt
        return total_count, total_amount, agg

    if kind in ("summary", "trend", "ranking", "share", "comparison"):
        tc, ta, agg = build(start, end)
        rows = []
        for g, v in agg.items():
            row = {"group": g, "order_count": v["order_count"], "amount_cents": v["amount_cents"]}
            if kind == "share":
                row["share"] = ratio(v["amount_cents"], ta)
            rows.append(row)
        if kind == "ranking":
            rows.sort(key=lambda r: (-r["amount_cents"], r["group"]))
        else:
            rows.sort(key=lambda r: r["group"])
        result = {"kind": kind, "total": {"order_count": tc, "amount_cents": ta}, "rows": rows}
        if kind == "comparison":
            pc, pa, _ = build(prev_start, prev_end)
            delta = ta - pa
            result["rows"] = rows
            result["comparison"] = {
                "previous_order_count": pc,
                "previous_amount_cents": pa,
                "delta_cents": delta,
                "growth": ratio(delta, pa) if pa else (ratio(delta, pa)),
            }
            if not pa:
                result["comparison"]["growth"] = None
        return result

    if kind == "repeat_rate":
        inc = included(start, end)
        cust_state = {}
        order_by_cust = defaultdict(list)
        for o in sorted(inc, key=lambda o: (o.get(T) or "", o["order_id"])):
            c = customers.get(o.get("customer_id"))
            uid = (c or {}).get("customer_unique_id")
            if uid is None:
                continue
            order_by_cust[uid].append(o)
            if uid not in cust_state:
                cust_state[uid] = ((c or {}).get("customer_state") or "unknown")
        total_c = len(order_by_cust)
        total_r = sum(1 for v in order_by_cust.values() if len(v) >= 2)
        agg = {}
        for uid, ords in order_by_cust.items():
            g = cust_state[uid]
            if g not in agg:
                agg[g] = {"customer_count": 0, "repeat_customer_count": 0}
            agg[g]["customer_count"] += 1
            if len(ords) >= 2:
                agg[g]["repeat_customer_count"] += 1
        rows = [
            {
                "group": g,
                "customer_count": v["customer_count"],
                "repeat_customer_count": v["repeat_customer_count"],
                "repeat_rate": ratio(v["repeat_customer_count"], v["customer_count"]),
            }
            for g, v in sorted(agg.items(), key=lambda kv: kv[0])
        ]
        return {
            "kind": "repeat_rate",
            "total": {"customer_count": total_c, "repeat_customer_count": total_r, "repeat_rate": ratio(total_r, total_c)},
            "rows": rows,
        }

    if kind == "cohort_retention":
        H = plan.get("end")
        if H is None:
            max_t = None
            for o in orders:
                t = o.get(T)
                if t and (max_t is None or t > max_t):
                    max_t = t
            if max_t is None:
                H = "9999-12-31T23:59:59"
            else:
                from datetime import datetime, timedelta
                H = (datetime.strptime(max_t[:19], "%Y-%m-%dT%H:%M:%S") + timedelta(seconds=1)).strftime("%Y-%m-%dT%H:%M:%S")
        activities = defaultdict(list)
        for o in orders:
            t = o.get(T)
            if o.get("order_status") in statuses and t and t < H:
                c = customers.get(o.get("customer_id"))
                uid = (c or {}).get("customer_unique_id")
                if uid is None:
                    continue
                activities[uid].append(t)
        cohorts = {}
        for uid, ts in activities.items():
            first = min(ts)
            if start is not None and first < start:
                continue
            cm = first[:7]
            cohorts.setdefault(cm, {"uids": set(), "months": defaultdict(set)})
            cohorts[cm]["uids"].add(uid)
            for t in ts:
                cohorts[cm]["months"][uid].add(t[:7])
        last_complete = None
        if H and len(H) >= 7:
            hy, hm = int(H[0:4]), int(H[5:7])
            if hm == 1:
                nm_y, nm_m = hy - 1, 12
            else:
                nm_y, nm_m = hy, hm - 1
            nm_first = "%04d-%02d-01T00:00:00" % (nm_y, nm_m)
            if nm_first <= H:
                last_complete = "%04d-%02d" % (nm_y, nm_m)
        rows = []
        total_cust = 0
        if last_complete:
            for cm in sorted(cohorts):
                if not (month_next(cm) <= (last_complete + "-01T00:00:00")):
                    continue
                uids = cohorts[cm]["uids"]
                months_map = cohorts[cm]["months"]
                total_cust += len(uids)
                for off in range(0, 7):
                    try:
                        y = int(cm[0:4]); mo = int(cm[5:7]) + off
                        y += (mo - 1) // 12
                        mo = (mo - 1) % 12 + 1
                        tm = "%04d-%02d" % (y, mo)
                    except Exception:
                        break
                    if not (month_next(tm) <= (last_complete + "-01T00:00:00")):
                        break
                    retained = sum(1 for uid in uids if tm in months_map.get(uid, ()))
                    rows.append({
                        "cohort": cm,
                        "offset": off,
                        "customer_count": len(uids),
                        "retained_count": retained,
                        "retention": ratio(retained, len(uids)),
                    })
        return {"kind": "cohort_retention", "total": {"customer_count": total_cust, "last_complete_month": last_complete}, "rows": rows}

    if kind == "delivery_delay":
        inc = included(start, end)
        agg = defaultdict(lambda: {"delivered_count": 0, "late_count": 0})
        td = 0
        tl = 0
        for o in inc:
            if o.get("order_status") != "delivered":
                continue
            d = o.get("order_delivered_customer_date")
            e_est = o.get("order_estimated_delivery_date")
            if not d or not e_est:
                continue
            td += 1
            if d[:10] > e_est[:10]:
                tl += 1
            if group_by:
                if group_by == "customer_state":
                    c = customers.get(o.get("customer_id"))
                    g = (c or {}).get("customer_state") or "unknown"
                else:
                    g = str(o.get(group_by))
                agg[g]["delivered_count"] += 1
                if d[:10] > e_est[:10]:
                    agg[g]["late_count"] += 1
        rows = [
            {"group": g, "delivered_count": v["delivered_count"], "late_count": v["late_count"], "late_rate": ratio(v["late_count"], v["delivered_count"])}
            for g, v in sorted(agg.items(), key=lambda kv: kv[0])
        ]
        return {"kind": "delivery_delay", "total": {"delivered_count": td, "late_count": tl, "late_rate": ratio(tl, td)}, "rows": rows}

    if kind == "category_sales":
        translation = {t["product_category_name"]: t["product_category_name_english"] for t in data.get("category_translation", [])}
        products = {p["product_id"]: p for p in data.get("products", [])}
        inc_ids = {o["order_id"] for o in included(start, end)}
        agg = {}
        total_orders = set()
        ti = 0
        tp = 0
        tf = 0
        for it in data.get("order_items", []):
            if it["order_id"] not in inc_ids:
                continue
            p = products.get(it.get("product_id"))
            raw = (p or {}).get("product_category_name")
            if not raw:
                cat = "unknown"
            else:
                cat = translation.get(raw, raw)
            price = int(it.get("price_cents") or 0)
            freight = int(it.get("freight_cents") or 0)
            v = agg.setdefault(cat, {"order_ids": set(), "item_count": 0, "price_cents": 0, "freight_cents": 0})
            v["order_ids"].add(it["order_id"])
            v["item_count"] += 1
            v["price_cents"] += price
            v["freight_cents"] += freight
            total_orders.add(it["order_id"])
            ti += 1
            tp += price
            tf += freight
        rows = [
            {"group": g, "order_count": len(v["order_ids"]), "item_count": v["item_count"], "price_cents": v["price_cents"], "freight_cents": v["freight_cents"]}
            for g, v in agg.items()
        ]
        rows.sort(key=lambda r: (-r["price_cents"], r["group"]))
        return {
            "kind": "category_sales",
            "total": {"order_count": len(total_orders), "item_count": ti, "price_cents": tp, "freight_cents": tf},
            "rows": rows,
        }

    return {"kind": kind, "total": {}, "rows": []}
